  window.psProductionDetail=async function(id){const d=await api('/api/pink-salt/production/'+id);modal(`<h2>${esc(t('Production Batch'))} · ${esc(d.batch_no)}</h2><div class="ps-detail-grid"><div class="ps-detail-box"><small>${esc(t('Raw Salt Inputs by Category'))}</small><b>${esc(d.raw_sources||'—')}</b></div><div class="ps-detail-box"><small>${esc(t('Input Weight (kg)'))}</small><b>${qty(d.input_weight_kg)} kg</b></div><div class="ps-detail-box"><small>${esc(t('Actual Output'))}</small><b>${qty(d.actual_output_weight_kg)} kg</b></div><div class="ps-detail-box"><small>${esc(t('Waste Weight'))}</small><b>${qty(d.waste_weight_kg)} kg</b></div></div><div class="ps-two" style="margin-top:12px"><div class="card"><h3>${esc(t('Raw Salt Inputs by Category'))}</h3>${d.inputs.map(x=>`<div class="ps-mini"><span><b>${esc(x.salt_grade)}</b><small>${esc(x.import_no)} · ${esc(x.container_no||'')}</small></span><span><b>${qty(x.input_weight_kg,3)} kg</b><small>${esc(t('Required Salt Weight'))} ${qty(x.required_output_weight_kg,3)} kg · ${esc(t('Waste Weight'))} ${qty(x.waste_weight_kg,3)} kg</small></span></div>`).join('')}</div><div class="card"><h3>${esc(t('Finished Outputs'))}</h3>${d.outputs.map(x=>`<div class="ps-mini"><span><b>${esc(x.sku)}</b><small>${esc(x.name)}</small></span><span><b>${qty(x.quantity_units,0)} units</b><small>${qty(x.output_weight_kg,3)} kg · ${fmt(x.unit_cost_krw)} / unit</small></span></div>`).join('')}</div></div><div class="card" style="margin-top:12px"><h3>${esc(t('Packaging Needed'))}</h3>${d.packaging.map(x=>`<div class="ps-mini"><span><b>${esc(x.sku)}</b><small>${esc(t(x.category))} · ${esc(x.name)}</small></span><b>${qty(x.quantity_used)}</b></div>`).join('')||'—'}</div><div class="card" style="margin-top:12px"><h3>${esc(t('Attachments'))}</h3>${d.attachments.map(a=>`<div class="ps-mini"><span>${esc(a.title)}</span><a class="btn small" href="${esc(a.file_path)}" target="_blank">${esc(t('Open'))}</a></div>`).join('')||'—'}</div><div class="actions"><button class="btn" onclick="closeModal()">${esc(t('Close'))}</button></div>`,'wide')};

  async function psCustomers(c){const rows=await api('/api/pink-salt/customers');c.innerHTML=psTitle('Customers / Stores','Customer sales, receipts, outstanding balances and refundable credits.',`<button class="btn primary" onclick="psCustomerForm()">+ ${esc(t('New Customer / Store'))}</button>`)+`<div class="card"><div class="table-wrap"><table class="table"><tr><th>${esc(t('Customer / Store'))}</th><th>${esc(t('Customer Type'))}</th><th>${esc(t('Sales Channel'))}</th><th>${esc(t('Completed Orders'))}</th><th>${esc(t('Lifetime Sales'))}</th><th>${esc(t('Paid Amount'))}</th><th>${esc(t('Outstanding'))}</th><th>${esc(t('Customer Credit'))}</th><th></th></tr>${rows.map(x=>`<tr><td><b>${esc(x.name)}</b><div class="muted">${esc(x.email||x.phone||'')}</div></td><td>${esc(t(x.customer_type))}</td><td>${esc(x.sales_channel||'—')}</td><td>${x.completed_orders||0}</td><td>${fmt(x.lifetime_sales_krw)}</td><td>${fmt(x.paid_krw)}</td><td><b>${fmt(x.outstanding_krw)}</b></td><td>${fmt(x.customer_credit_krw)}</td><td><button class="btn small" onclick="psCustomerForm(${x.id})">${esc(t('Edit'))}</button></td></tr>`).join('')||`<tr><td colspan="9"><div class="empty">${esc(t('No records.'))}</div></td></tr>`}</table></div></div>`;translateElement(c)}
  window.psCustomerForm=async function(id){const rows=id?await api('/api/pink-salt/customers'):[],x=id?rows.find(z=>z.id==id):null;modal(`<h2>${esc(t(id?'Edit Customer / Store':'New Customer / Store'))}</h2><form onsubmit="psSaveCustomer(event,${id||0})"><div class="grid g2"><div class="field"><label>${esc(t('Customer / Store'))} *</label><input name="name" value="${esc(x?.name||'')}" required placeholder="Store / company / marketplace account"></div><div class="field"><label>${esc(t('Customer Type'))}</label><select name="customer_type">${['Ecommerce','Local Store','Wholesale','Corporate / Gift','Direct'].map(z=>`<option ${x?.customer_type===z?'selected':''}>${esc(t(z))}</option>`).join('')}</select></div></div><div class="grid g3"><div class="field"><label>${esc(t('Sales Channel'))}</label><input name="sales_channel" value="${esc(x?.sales_channel||'')}" placeholder="Coupang / Naver / Offline / Direct"></div><div class="field"><label>${esc(t('Contact Person'))}</label><input name="contact_person" value="${esc(x?.contact_person||'')}"></div><div class="field"><label>${esc(t('Phone'))}</label><input name="phone" value="${esc(x?.phone||'')}"></div></div><div class="grid g2"><div class="field"><label>${esc(t('Email'))}</label><input name="email" type="email" value="${esc(x?.email||'')}"></div><div class="field"><label>${esc(t('Address'))}</label><input name="address" value="${esc(x?.address||'')}"></div></div><div class="field"><label>${esc(t('Notes'))}</label><textarea name="notes">${esc(x?.notes||'')}</textarea></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">${esc(t('Cancel'))}</button><button class="btn primary">${esc(t('Save'))}</button></div></form>`)};
